BEGIN;
ALTER TABLE users ADD COLUMN IF NOT EXISTS role TEXT NOT NULL DEFAULT 'student' CHECK(role IN ('student','teacher','admin'));
ALTER TABLE users ADD COLUMN IF NOT EXISTS status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive'));
CREATE TABLE IF NOT EXISTS profiles (
 user_id BIGINT PRIMARY KEY REFERENCES users ON DELETE CASCADE,
 phone TEXT NOT NULL DEFAULT '', address TEXT NOT NULL DEFAULT '', student_number TEXT UNIQUE,
 year_level INTEGER CHECK(year_level BETWEEN 1 AND 8), emergency_name TEXT NOT NULL DEFAULT '', emergency_phone TEXT NOT NULL DEFAULT '',
 timezone TEXT NOT NULL DEFAULT 'Asia/Manila', language TEXT NOT NULL DEFAULT 'en', theme TEXT NOT NULL DEFAULT 'light' CHECK(theme IN ('light','dark')),
 notify_assignments BOOLEAN NOT NULL DEFAULT true, notify_announcements BOOLEAN NOT NULL DEFAULT true, notify_grades BOOLEAN NOT NULL DEFAULT true
);
CREATE TABLE IF NOT EXISTS departments(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS programs(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL UNIQUE, department_id BIGINT REFERENCES departments);
ALTER TABLE profiles ADD COLUMN IF NOT EXISTS program_id BIGINT REFERENCES programs;
CREATE TABLE IF NOT EXISTS terms(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL UNIQUE, starts_on DATE NOT NULL, ends_on DATE NOT NULL, CHECK(ends_on >= starts_on));
CREATE TABLE IF NOT EXISTS rooms(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL UNIQUE, capacity INTEGER NOT NULL CHECK(capacity BETWEEN 1 AND 10000));
CREATE TABLE IF NOT EXISTS courses(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, credits NUMERIC(4,1) NOT NULL CHECK(credits > 0 AND credits <= 30), description TEXT NOT NULL DEFAULT '', department_id BIGINT REFERENCES departments);
CREATE TABLE IF NOT EXISTS sections(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, course_id BIGINT NOT NULL REFERENCES courses, term_id BIGINT NOT NULL REFERENCES terms, teacher_id BIGINT NOT NULL REFERENCES users, name TEXT NOT NULL, capacity INTEGER NOT NULL CHECK(capacity BETWEEN 1 AND 10000), archived BOOLEAN NOT NULL DEFAULT false, UNIQUE(course_id,term_id,name));
CREATE INDEX IF NOT EXISTS sections_teacher_idx ON sections(teacher_id);
CREATE TABLE IF NOT EXISTS enrollments(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, section_id BIGINT NOT NULL REFERENCES sections, student_id BIGINT NOT NULL REFERENCES users, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','withdrawn')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(section_id,student_id));
CREATE INDEX IF NOT EXISTS enrollments_student_idx ON enrollments(student_id);
CREATE TABLE IF NOT EXISTS meetings(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, section_id BIGINT NOT NULL REFERENCES sections, room_id BIGINT NOT NULL REFERENCES rooms, weekday INTEGER NOT NULL CHECK(weekday BETWEEN 1 AND 7), starts_at TIME NOT NULL, ends_at TIME NOT NULL, CHECK(ends_at > starts_at));
CREATE TABLE IF NOT EXISTS class_sessions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, section_id BIGINT NOT NULL REFERENCES sections, held_on DATE NOT NULL, title TEXT NOT NULL, cancelled BOOLEAN NOT NULL DEFAULT false, UNIQUE(section_id,held_on,title));
CREATE TABLE IF NOT EXISTS attendance(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, session_id BIGINT NOT NULL REFERENCES class_sessions, student_id BIGINT NOT NULL REFERENCES users, status TEXT NOT NULL CHECK(status IN ('present','absent','late','excused')), note TEXT NOT NULL DEFAULT '', updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(session_id,student_id));
CREATE TABLE IF NOT EXISTS assessments(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, section_id BIGINT NOT NULL REFERENCES sections, title TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('assignment','exam','other')), points NUMERIC(8,2) NOT NULL CHECK(points > 0 AND points <= 100000), weight NUMERIC(6,2) NOT NULL CHECK(weight > 0 AND weight <= 100), published BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS assignments(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, assessment_id BIGINT NOT NULL UNIQUE REFERENCES assessments, instructions TEXT NOT NULL DEFAULT '', due_at TIMESTAMPTZ NOT NULL, allow_late BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS submissions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, assignment_id BIGINT NOT NULL REFERENCES assignments, student_id BIGINT NOT NULL REFERENCES users, content TEXT NOT NULL CHECK(length(content) BETWEEN 1 AND 12000), submitted_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(assignment_id,student_id));
CREATE TABLE IF NOT EXISTS submission_versions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, submission_id BIGINT NOT NULL REFERENCES submissions ON DELETE CASCADE, content TEXT NOT NULL, submitted_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS scores(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, assessment_id BIGINT NOT NULL REFERENCES assessments, student_id BIGINT NOT NULL REFERENCES users, points NUMERIC(8,2) NOT NULL CHECK(points >= 0), feedback TEXT NOT NULL DEFAULT '', published BOOLEAN NOT NULL DEFAULT false, updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(assessment_id,student_id));
CREATE TABLE IF NOT EXISTS exams(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, assessment_id BIGINT NOT NULL UNIQUE REFERENCES assessments, starts_at TIMESTAMPTZ NOT NULL, ends_at TIMESTAMPTZ NOT NULL, room_id BIGINT NOT NULL REFERENCES rooms, instructions TEXT NOT NULL DEFAULT '', CHECK(ends_at > starts_at));
CREATE TABLE IF NOT EXISTS materials(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, section_id BIGINT NOT NULL REFERENCES sections, title TEXT NOT NULL, content TEXT NOT NULL DEFAULT '', url TEXT NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS announcements(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, author_id BIGINT NOT NULL REFERENCES users, section_id BIGINT REFERENCES sections, title TEXT NOT NULL, content TEXT NOT NULL, pinned BOOLEAN NOT NULL DEFAULT false, publish_at TIMESTAMPTZ NOT NULL DEFAULT now(), expires_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK(expires_at IS NULL OR expires_at > publish_at));
CREATE TABLE IF NOT EXISTS announcement_reads(announcement_id BIGINT REFERENCES announcements ON DELETE CASCADE, user_id BIGINT REFERENCES users ON DELETE CASCADE, read_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(announcement_id,user_id));
CREATE TABLE IF NOT EXISTS notifications(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users ON DELETE CASCADE, title TEXT NOT NULL, href TEXT NOT NULL, read_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS notifications_user_idx ON notifications(user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS school_settings(key TEXT PRIMARY KEY, value JSONB NOT NULL);
INSERT INTO school_settings(key,value) VALUES('school','{"name":"School Hub","timezone":"Asia/Manila","attendance_threshold":75}') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS audit_logs(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, actor_id BIGINT REFERENCES users ON DELETE SET NULL, action TEXT NOT NULL, entity TEXT NOT NULL, entity_id BIGINT, details JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_created_idx ON audit_logs(created_at DESC);
COMMIT;
